INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('zeitumstellung-winterzeit-2026-oesterreich-uhren-zurueck','Zeitumstellung heute Nacht: Uhren um 3 Uhr auf 2 Uhr zurückstellen','In der Nacht auf Sonntag endet die Sommerzeit: Um 3 Uhr springen die Uhren auf 2 Uhr zurück. Die Regierung hat die Termine bis 2031 bereits festgelegt.','Die **Zeitumstellung** steht in der Nacht von Samstag auf Sonntag, 25. Oktober 2026, an: Um 3 Uhr Sommerzeit werden die Uhren in Österreich auf 2 Uhr Normalzeit zurückgedreht. Wer schläft, gewinnt damit eine zusätzliche Stunde. Ab Sonntag gilt wieder die Mitteleuropäische Zeit (MEZ), die in Österreich laut Gesetz die reguläre Zeit ist.

Heuer fällt der Wechsel so früh wie nur möglich. Die Sommerzeit endet EU-weit immer am letzten Sonntag im Oktober, und der 25. ist das frühestmögliche Datum für diesen Sonntag.

## Was bei der Zeitumstellung zu tun ist

Die meisten Geräte erledigen den Wechsel selbst. Für einen entspannten Sonntag lohnt aber ein kurzer Rundgang durch die Wohnung:

- **Automatisch:** Smartphones, Computer, Tablets und Funkuhren stellen sich in der Regel ohne Zutun um.
- **Händisch:** Uhren an Herd, Mikrowelle und Backofen, im Auto sowie viele klassische Wecker müssen von Hand um eine Stunde zurückgestellt werden.
- **Termine:** Wer am Sonntag früh einen Zug, Flug oder Dienst hat, sollte sich auf ein automatisch umgestelltes Gerät verlassen oder die Weckzeit doppelt prüfen.

Mit der Rückkehr zur Normalzeit wird es am Morgen früher hell, dafür bricht die Dunkelheit am Abend eine Stunde zeitiger herein.

## Regierung legt Sommerzeit bis 2031 fest

Rechtlich ist der Wechsel auch ein Abschluss: Die derzeit geltende Sommerzeit-Verordnung umfasst die Jahre 2022 bis 2026. Die Umstellung am Sonntag ist damit die letzte, die sie regelt.

Für die Folgejahre hat Wirtschaftsminister Wolfgang Hattmannsdorfer (ÖVP) dem Ministerrat am 22. September eine neue Verordnung für die Kalenderjahre 2027 bis 2031 vorgelegt. Grundlage ist das Zeitzählungsgesetz aus dem Jahr 1976, das die Bundesregierung verpflichtet, Beginn und Ende der Sommerzeit per Verordnung festzulegen. Die Daten folgen einer Mitteilung der EU-Kommission, die im März im Amtsblatt der Europäischen Union veröffentlicht wurde.

Die Termine im Überblick (Beginn jeweils um 2 Uhr, Ende um 3 Uhr):

1. 2027: 28. März bis 31. Oktober
2. 2028: 26. März bis 29. Oktober
3. 2029: 25. März bis 28. Oktober
4. 2030: 31. März bis 27. Oktober
5. 2031: 30. März bis 26. Oktober

## Warum die Zeitumstellung nicht abgeschafft ist

Die EU-Kommission hatte bereits im September 2018 vorgeschlagen, die halbjährliche Zeitumstellung zu beenden. Das Europäische Parlament stimmte im März 2019 zu. Seither fehlt jedoch eine gemeinsame Linie der Mitgliedstaaten im Rat.

Umstritten ist vor allem, ob dauerhaft die Sommer- oder die Normalzeit gelten soll und wie sich Nachbarländer abstimmen, damit kein Flickenteppich unterschiedlicher Zeitzonen entsteht. Die Kommission hat dazu eine weitere Studie in Auftrag gegeben, deren Ergebnisse bis Ende 2026 erwartet werden. Bis zu einer Einigung gilt die EU-Richtlinie aus dem Jahr 2000 weiter, wonach alle Mitgliedstaaten gleichzeitig um 1 Uhr Weltzeit umstellen.

## Lange Geschichte der Sommerzeit in Österreich

Ganz neu ist das Hin und Her nicht. Eine Sommerzeit gab es in Österreich bereits von 1916 bis 1920 sowie von 1940 bis 1948. Seit 1980 wird wieder regelmäßig umgestellt. Der nächste Wechsel auf Sommerzeit folgt am 28. März 2027, dann wird die Uhr um 2 Uhr auf 3 Uhr vorgestellt.','chronik','Österreich',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/zeitumstellung-winterzeit-2026-oesterreich-uhren-zurueck.webp','Bundeskanzleramt – Ministerrat vom 22. September 2026','https://www.bundeskanzleramt.gv.at/bundeskanzleramt/die-bundesregierung/ministerratsprotokolle/ministerratsprotokolle-regierungsperiode-xxviii-2025/bp-63-22-sep.html','published','2026-10-24T19:50:00.000Z','2026-10-24T19:44:43.601Z','Zeitumstellung 2026: Uhren heute Nacht zurückstellen','Zeitumstellung in der Nacht auf 25. Oktober: Um 3 Uhr werden die Uhren auf 2 Uhr gestellt. Was das bedeutet und welche Termine bis 2031 gelten.','Zeitumstellung','["Zeitumstellung","Winterzeit 2026","Uhren zurückstellen","Zeitumstellung Oktober 2026","Sommerzeit Ende","Zeitumstellung Österreich","Sommerzeit Termine bis 2031","Zeitumstellung abschaffen EU"]','Zeitumstellung: Analoge Uhr wird in einer Wiener Wohnung um eine Stunde zurückgestellt','Night scene in a cozy Viennese apartment kitchen, an analog wall clock and an old-fashioned bedside alarm clock on a wooden table, hand of a person adjusting the clock hands, warm lamp light, window view of illuminated Vienna rooftops at night, photorealistic','[{"q":"Wann ist die Zeitumstellung 2026?","a":"In der Nacht auf Sonntag, 25. Oktober 2026. Um 3 Uhr werden die Uhren auf 2 Uhr zurückgestellt."},{"q":"Wird die Zeitumstellung abgeschafft?","a":"Vorerst nicht. Die EU-Staaten haben sich bisher nicht geeinigt, Österreich hat die Termine bereits bis 2031 festgelegt."},{"q":"Wann wird 2027 wieder auf Sommerzeit umgestellt?","a":"Am 28. März 2027 wird die Uhr um 2 Uhr auf 3 Uhr vorgestellt."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.tease